"""Build static, progressively enhanced pages from the checked-in resource manifest."""
import json,re,html,hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[1]; resources=json.loads((R/'data/resources.json').read_text()); esc=html.escape
BOOK='https://quarcs-lab.github.io/macro102-site/'
def versioned(path):
 return path+'?v='+hashlib.sha256((R/path).read_bytes()).hexdigest()[:12]
byid={r['id']:r for r in resources}
editorial=json.loads((R/'data/curriculum.json').read_text())
widgets=(R/'audio-player/players.html').read_text()
chunks=re.split(r'(?=<div class="podcast-widget" id=)',widgets)[1:]
players={r['id']:chunk for r,chunk in zip([r for r in resources if 'podcast' in r],chunks)}
player_assets='<link rel="stylesheet" href="audio-player/podcast-player.css"><script src="audio-player/podcast-player.js" defer></script>'
nav=[('Home','index.html'),('Book',BOOK),('AI Podcasts','podcasts.html'),('AI Tutors','tutors.html'),('Data Apps','data-apps.html'),('Figure Apps','figure-apps.html')]
def page(name,title,description,body):
 links=''.join(f'<a href="{url}"'+(' aria-current="page"' if url==name else '')+f'>{label}</a>' for label,url in nav)
 extra=('<link rel="stylesheet" href="'+versioned('assets/home.css')+'">') if name=='index.html' else ''
 if name in ('data-apps.html','figure-apps.html'): extra='<link rel="stylesheet" href="'+versioned('assets/apps.css')+'">'
 if name=='podcasts.html': extra=player_assets+'<link rel="stylesheet" href="'+versioned('assets/podcasts.css')+'"><script src="'+versioned('assets/podcasts.js')+'" defer></script>'
 s=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | Data Science &amp; Macroeconomics</title><meta name="description" content="{esc(description)}"><meta name="theme-color" content="#0b1425"><meta property="og:title" content="{esc(title)} — Data Science &amp; Macroeconomics"><meta property="og:description" content="{esc(description)}"><meta property="og:image" content="https://quarcs-lab.github.io/macro102-hub/assets/economic-world.jpg"><meta property="og:type" content="website"><link rel="canonical" href="https://quarcs-lab.github.io/macro102-hub/{'' if name=='index.html' else name}"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><script src="assets/theme.js"></script><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;450;500;550;600;650;700;750;800&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet"><link rel="stylesheet" href="{versioned('assets/site.css')}"><script src="{versioned('assets/site.js')}" defer></script>{extra}</head><body><a class="skip" href="#main">Skip to content</a><header class="header"><div class="nav-shell"><a class="brand" href="index.html"><span class="brand-mark" aria-hidden="true">m<span>↗</span></span><span>Data Science <span class="brand-second">&amp; Macroeconomics</span></span></a><nav id="navigation" aria-label="Main navigation">{links}</nav><button class="icon-button" id="theme-toggle" aria-label="Switch to light theme" title="Switch theme">☼</button><button class="menu-button" aria-controls="navigation" aria-expanded="false">Menu</button></div></header><main id="main">{body}</main><footer><div class="shell footer-inner"><div><a class="brand" href="index.html">Data Science &amp; Macroeconomics</a><p>A Python Companion to Intermediate Macroeconomics.</p><p>By <a href="https://carlos-mendez.org/">Carlos Mendez</a> · <a href="{BOOK}">Read the book ↗</a></p></div><div class="footer-meta"><a href="https://github.com/quarcs-lab/macro102-hub">Source on GitHub ↗</a><a href="https://github.com/quarcs-lab/macro102-hub/issues">Report an issue ↗</a><p>© 2026 Carlos Mendez · <a href="https://creativecommons.org/licenses/by-nc/4.0/">CC BY-NC 4.0</a></p></div></div><div class="shell credit">Companion to <a href="https://web.stanford.edu/~chadj/" target="_blank" rel="noopener">Charles I. Jones</a>, <a href="https://web.stanford.edu/~chadj/macrobook.html" target="_blank" rel="noopener"><em>Macroeconomics</em></a> (6th ed., 2024). Independent educational project; not affiliated with the author or publisher. Original website illustrations generated with AI.</div></footer></body></html>'''
 (R/name).write_text(s)
def intro(kicker,title,desc): return f'<section class="page-intro shell"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{desc}</p></section>'
def searchbox(label): return f'<div class="filter-bar"><label>Search {label}<input type="search" id="resource-search" placeholder="Try growth, inflation, or Chapter 7…"></label><label>Topic<select id="topic-filter"><option value="">All topics</option>'+''.join(f'<option>{esc(g)}</option>' for g in dict.fromkeys(r['group'] for r in resources))+'</select></label><p id="result-count" role="status"></p></div>'
slides=[
('growth','Long-run growth','Why are some countries<br>so much richer?','Start with the differences in living standards. Then ask what capital, ideas, and institutions can explain.','ch03','Data · Maddison Project · 1950–2022','GDP per person for the United States, Japan, China, and India from 1950 to 2022.'),
('recessions','Business cycles','Why do economies<br>fall into recession?','Follow output through financial crises and the pandemic. See how far an economy can move from its potential.','ch10','Data · U.S. output gap · BEA / CBO via FRED','U.S. output relative to potential, including the financial crisis and pandemic.'),
('inflation','Prices & purchasing power','What drives<br>inflation?','Trace the history of rising prices, then connect money, expectations, and policy to the inflation rate.','ch08','Data · U.S. CPI inflation · FRED','Annual U.S. consumer price inflation from 1960 through 2025.'),
('employment','The labor market','Why does<br>unemployment persist?','Even in a growing economy, jobs are created and lost. A simple flow model explains a persistent natural rate.','ch07','Model · Job separation 1% · job finding 20% / month','Unemployment converges from 10 percent to a natural rate of 4.76 percent over 24 months.'),
('policy','Stabilization policy','How can policy<br>stabilize the economy?','Bring inflation and output into one diagram. Explore the trade-offs facing central banks after a shock.','ch13','Model · AS/AD · book baseline parameters','Aggregate supply and demand intersect at a zero output gap and 2 percent inflation.'),
('global','The global economy','How do trade and exchange<br>rates connect economies?','Follow prices and interest rates across borders. Explore how international connections reshape domestic choices.','ch20','Model · Uncovered interest parity · one-year horizon','The exchange rate rises with the domestic interest rate, holding foreign interest and expected exchange rates fixed.')]
slide_html=''
for i,(id,topic,q,desc,ch,source,alt) in enumerate(slides):
 slide_html+=f'<article class="question-slide" data-slide="{i}" aria-label="{i+1} of 6: {topic}"'+(' hidden' if i else '')+f'><img class="scene-art" src="assets/scenes/{id}.jpg" alt="" aria-hidden="true" width="1200" height="800" loading="{"eager" if i == 0 else "lazy"}" decoding="async"><div class="slide-intro"><p class="eyebrow">{topic}</p><h2>{q}</h2></div><img class="chart" src="{versioned(f'assets/charts/{id}.svg')}" alt="{alt}" width="640" height="360"><div class="slide-caption"><p>{desc}</p><div class="chart-meta">{source}</div><a href="{byid[ch]["book"]}">Explore Chapter {int(ch[2:])} <span aria-hidden="true">↗</span></a></div></article>'
topic_labels=['Growth','Recessions','Inflation','Employment','Policy','Global']
selectors=''.join(f'<button class="question-selector" data-go="{i}" aria-label="Show question {i+1}: {label}" aria-pressed="{str(i==0).lower()}">{label}</button>' for i,label in enumerate(topic_labels))
hero=f'''<section class="hero" aria-labelledby="page-title"><div class="hero-orbit" aria-hidden="true"></div><div class="shell hero-grid"><div class="hero-copy"><p class="eyebrow"><span class="status-dot"></span> A FIELD GUIDE TO THE WHOLE ECONOMY</p><h1 id="page-title">Data Science<br><span>&amp; Macroeconomics.</span></h1><p class="hero-hook">Find the facts.<br>Explain the economy.</p><p class="hero-description">Why do living standards rise? What causes recessions and inflation? Explore the data, put models to work, and ask better questions—with Python and AI.</p><div class="actions"><a class="button primary" href="{byid['ch01']['book']}">Start with Chapter 1 <span aria-hidden="true">↗</span></a><a class="text-link" href="#curriculum">Explore all chapters <span aria-hidden="true">↓</span></a></div><p class="hero-welcome">A Python Companion to Intermediate Macroeconomics.</p></div><div class="hero-author"><img src="https://github.com/cmg777.png" alt="Carlos Mendez" width="72" height="72"><div><p>A learning project by <a href="https://carlos-mendez.org/">Carlos Mendez</a></p><p>A companion to <a href="https://web.stanford.edu/~chadj/macrobook.html" target="_blank" rel="noopener"><em>Macroeconomics</em></a><br>by <a href="https://web.stanford.edu/~chadj/" target="_blank" rel="noopener">Charles I. Jones</a> · 6th edition.</p></div></div><div class="question-deck" role="region" aria-roledescription="carousel" aria-label="Six big questions in macroeconomics"><div class="deck-header"><span>SIX BIG QUESTIONS</span><span id="slide-count">01 / 06</span></div><div class="slides">{slide_html}</div><div class="carousel-controls"><div class="question-selectors" aria-label="Choose a topic">{selectors}</div><div class="transport"><button id="previous-slide" aria-label="Previous question">←</button><button id="pause-slides" aria-label="Pause automatic rotation" aria-pressed="false">Ⅱ Pause</button><button id="next-slide" aria-label="Next question">→</button><span id="rotation-status">Changes every 10 seconds</span></div></div></div></div><div class="shell hero-bottom"><p><strong>21</strong> chapters <span>/</span> <strong>9</strong> appendices <span>/</span> Learn by doing</p><a href="#pathways">From data to understanding <span aria-hidden="true">↓</span></a></div></section>'''
pillars='''<section class="section shell learning-path" id="pathways" aria-labelledby="pillars-title"><div class="section-heading"><p class="eyebrow">THREE PILLARS. ONE CONNECTED APPROACH.</p><h2 id="pillars-title">From evidence<br>to explanation.</h2><p>Find a pattern. Build an explanation.<br>Use AI to go further—and check every step.</p></div><ol class="pillars"><li><span class="large-number">01 / DATA SCIENCE</span><h3>From data to facts</h3><p>Download, plot, and explore real economic data. Compare countries and periods to discover which patterns hold—and which questions to ask next.</p><a href="data-apps.html">Explore Data Apps <span aria-hidden="true">↗</span></a></li><li><span class="large-number">02 / MACROECONOMIC MODELS</span><h3>From facts to models</h3><p>Operate the models that explain the facts. Move a slider, change a parameter, and compare the prediction with what the data show.</p><a href="figure-apps.html">Explore Figure Apps <span aria-hidden="true">↗</span></a></li><li><span class="large-number">03 / AI-POWERED LEARNING</span><h3>AI-powered learning</h3><p>Work with an AI assistant in Colab, see the big picture in mind maps and slides, and learn by changing the code. Use AI, but check its answers.</p><a href="https://quarcs-lab.github.io/macro102-site/notebooks/appA-google-colab-and-ai-powered-python.html">Start with Python and AI <span aria-hidden="true">↗</span></a></li></ol></section>'''
def curriculum_card(r):
 e=editorial[r['id']]; chapter=r['id'].startswith('ch'); number=r['id'][2:] if chapter else r['id'][-1]
 anchor=f"chapter-{int(number)}" if chapter else f"appendix-{number.lower()}"
 actions=[('↗','Read chapter' if chapter else 'Read appendix',r['book']),('</>','Open AI notebook',r['colab'])]
 if r.get('slides'): actions.append(('▤','Slides',r['slides']))
 for kind,label,icon in [('data','Data Apps','↗'),('model','Figure Apps','↗')]:
  if kind in r['apps']: actions.append((icon,label,r['apps'][kind]['url']))
 links=''.join(f'<a class="chapter-action{ " chapter-action-primary" if i==0 else ""}" href="{esc(url)}" target="_blank" rel="noopener"><span aria-hidden="true">{esc(icon)}</span>{label}</a>' for i,(icon,label,url) in enumerate(actions))
 player=players.get(r['id'],'').replace('Listen AI Podcast','Listen to the podcast')
 tag='<span class="chapter-tag">Start here</span>' if r['id']=='ch01' else ''
 return f'''<article id="{anchor}" class="chapter-card resource" data-topic="{esc(r['group'])}" data-search="{esc(r['label']+' '+r['title']+' '+e['question']+' '+r['group'])}" aria-labelledby="title-{r['id']}"><div class="chapter-top"><span class="chapter-number">{number}</span><span class="chapter-method">{esc(r['title'])}</span>{tag}</div><div class="chapter-story"><h3 id="title-{r['id']}">{esc(e['question'])}</h3><p>{esc(e['introduction'])}</p></div><a class="chapter-thumb" href="{esc(r['mindmap'])}" data-map-title="{esc(r['label']+': '+r['title'])}" aria-label="Enlarge {esc(r['label'])} mind map" target="_blank" rel="noopener"><img src="{r['preview']}" alt="{esc(r['label']+': '+r['title'])} mind map" loading="lazy" width="900" height="600"><span class="art-caption">Explore the chapter map <span aria-hidden="true">↗</span></span></a><div class="chapter-actions">{links}</div>{player}</article>'''
directory='<section class="home-curriculum" id="curriculum" aria-labelledby="curriculum-title"><div class="shell"><span id="chapters" class="anchor-alias"></span><div class="section-heading curriculum-heading"><div><p class="eyebrow">THE FULL CURRICULUM</p><h2 id="curriculum-title">Understand the economy.<br><span>One question at a time.</span></h2></div><p>Follow the chapters in order, or start with the question on your mind. Read, code, explore, or listen—each chapter gives you a way in.</p></div>'+searchbox('the curriculum')+player_assets
for group in dict.fromkeys(r['group'] for r in resources if r['id'].startswith('ch')):
 directory+=f'<section class="curriculum-group" aria-label="{esc(group)}"><h3 class="group-title">{esc(group)}</h3><div class="chapter-grid">'+''.join(curriculum_card(r) for r in resources if r['group']==group)+'</div></section>'
directory+='<details class="appendices" id="appendices"><summary><span><strong>Nine appendices</strong><small>Python, data, mathematical tools, and research extensions</small></span><span class="overview-toggle" aria-hidden="true">+</span></summary><div class="chapter-grid">'+''.join(curriculum_card(r) for r in resources if r['id'].startswith('app'))+'</div></details><p class="empty" hidden>No matching chapters or appendices. Try another search or topic.</p><p class="curriculum-credit">Mind maps and lecture slides accompany every chapter and appendix. AI-generated podcasts accompany all 21 chapters.</p></div></section>'
viewer='''<dialog id="mindmap-viewer" aria-labelledby="mindmap-title"><div class="viewer-bar"><h2 id="mindmap-title">Chapter mind map</h2><div><a id="mindmap-original" target="_blank" rel="noopener">Open original ↗</a><button type="button" id="close-mindmap" aria-label="Close mind map">×</button></div></div><div class="viewer-image"><img id="mindmap-image" alt=""></div><p id="mindmap-status" role="status"></p></dialog>'''
page('index.html','Explore the book','Explore macroeconomics through real data, interactive models, Python notebooks, and AI podcasts. A companion by Carlos Mendez.',hero+pillars+directory+viewer)
# App collections share chapter questions and mind maps with the listening page.
for kind,name,label,hook,desc,featured_id in [
 ('data','data-apps.html','Data Apps','Find the facts.<br>Ask better questions.','Explore the evidence behind the book. Compare economies, trace changes over time, and discover the patterns that macroeconomic models aim to explain.','ch03'),
 ('model','figure-apps.html','Figure Apps','Change an assumption.<br>See the economy respond.','Put the book’s models to work. Explore interactive figures, change parameters, and follow the mechanisms connecting growth, employment, inflation, and policy.','ch05')]:
 available=[r for r in resources if kind in r['apps']]
 featured=byid[featured_id]; fe=editorial[featured_id]
 noun='data' if kind=='data' else 'model'
 feature_caption='Trace living standards across countries and centuries.' if kind=='data' else 'Explore saving, capital accumulation, and the steady state.'
 body=f'''<div class="apps-page"><section class="apps-hero shell" aria-labelledby="page-title"><div class="apps-hero-copy"><p class="eyebrow"><span class="status-dot" aria-hidden="true"></span>{len(available)} CHAPTER COLLECTIONS. LEARN BY DOING.</p><h1 id="page-title">{label.split()[0]} <span>Apps</span></h1><p class="apps-hook">{hook}</p><p class="apps-description">{desc}</p><div class="actions"><a class="button primary" href="#app-collections">Explore {label} <span aria-hidden="true">↓</span></a></div><p class="apps-hero-note">Start with a question. Open a chapter. Explore the {noun}.</p><div class="apps-facts"><span><strong>{len(available)}</strong> chapter collections</span><span><strong>Interactive</strong> exploration</span><span>From the book · Organized by chapter</span></div></div><figure class="apps-feature"><div class="apps-feature-top"><p class="eyebrow">FEATURED CHAPTER</p><span>{esc(featured['label'])}</span></div><a class="apps-feature-map" href="{esc(featured['mindmap'])}" target="_blank" rel="noopener" aria-label="Enlarge {esc(featured['label'])} mind map"><img src="{featured['preview']}" alt="{esc(featured['title'])} mind map" width="900" height="600" fetchpriority="high"><span>Explore the mind map <span aria-hidden="true">↗</span></span></a><p class="apps-feature-title">{esc(featured['title'])}</p><h2>{esc(fe['question'])}</h2><p class="apps-feature-description">{feature_caption}</p><figcaption><a href="{esc(featured['apps'][kind]['url'])}"><span class="apps-launch-icon" aria-hidden="true">↗</span><span>Open {label}<small>{esc(featured['label'])} collection</small></span><span class="apps-launch-arrow" aria-hidden="true">→</span></a></figcaption></figure></section><section class="apps-collection" id="app-collections" aria-labelledby="collection-title"><div class="shell"><div class="apps-collection-heading"><div><p class="eyebrow">EXPLORE BY CHAPTER</p><h2 id="collection-title">One question.<br><span>A way to explore it.</span></h2></div><p>Choose a chapter below. Use its mind map to see the big picture, then open the apps to investigate the details.</p></div>'''+searchbox('chapter collections')+'<div class="apps-chapter-grid">'
 for r in available:
  e=editorial[r['id']]; app=r['apps'][kind]
  searchable=' '.join([r['label'],r['title'],e['question'],r['group'],*[html.unescape(t) for t in app['topics']]])
  body+=f'''<article id="chapter-{int(r['id'][2:])}" class="apps-chapter-card resource" data-topic="{esc(r['group'])}" data-search="{esc(searchable)}" aria-labelledby="question-{r['id']}"><div class="apps-chapter-header"><span class="apps-chapter-number" aria-hidden="true">{r['id'][2:]}</span><div><p class="eyebrow">{esc(r['label'])} · {esc(r['group'])}</p><p class="apps-chapter-title">{esc(r['title'])}</p></div></div><h3 id="question-{r['id']}">{esc(e['question'])}</h3><p class="apps-chapter-description">{esc(e['introduction'])}</p><a class="apps-chapter-map" href="{esc(r['mindmap'])}" target="_blank" rel="noopener" aria-label="Enlarge {esc(r['label'])} mind map"><img src="{r['preview']}" alt="{esc(r['title'])} mind map" loading="lazy" width="900" height="600"><span>Explore the chapter map <span aria-hidden="true">↗</span></span></a><div class="apps-chapter-actions"><a class="button primary" href="{esc(app['url'])}">Open {label} <span aria-hidden="true">↗</span></a><a class="text-link" href="{esc(r['book'])}">Read chapter <span aria-hidden="true">↗</span></a></div></article>'''
 body+='</div><p class="empty" hidden>No matching chapter collections. Try another search or topic.</p>'
 if kind=='model': body+='<p class="apps-book-note">Figure Apps are called Model Apps in the book.</p>'
 body+='</div></section></div>'
 page(name,label,desc,body)
# The listening page adapts generated widgets; managed player files stay untouched.
episodes=[r for r in resources if 'podcast' in r]
config=json.loads((R/'player-config.json').read_text())
episode_config={r['id']:ep for r,ep in zip(episodes,config['episodes'])}
def duration_label(seconds):
 seconds=int(seconds)
 return f'{seconds//60:02d}:{seconds%60:02d}'
def listening_player(r):
 chunk=players[r['id']]
 chunk=re.sub(r'<div class="podcast-launch-row">.*?</div>', '', chunk, count=1, flags=re.S)
 chunk=re.sub(r'<noscript>.*?</noscript>', '', chunk, count=1, flags=re.S)
 chunk=re.sub(r'<a class="podcast-mindmap".*?</a>', '', chunk, count=1, flags=re.S)
 # Keep the runtime's disclosure hooks in the DOM, but show controls immediately here.
 ep=episode_config[r['id']]
 hook=f'<button hidden data-podcast-toggle aria-expanded="true" aria-controls="{ep["id"]}-player" type="button">Open audio player</button>'
 chunk=chunk.replace('<section ',hook+'<section ',1)
 chunk=chunk.replace('class="podcast-player"','class="podcast-player episode-player"',1)
 chunk=re.sub(r'(<section[^>]+) hidden>',r'\1 tabindex="-1">',chunk,count=1)
 chunk=chunk.replace('class="podcast-close"','hidden class="podcast-close"',1)
 return '\n'.join(line.rstrip() for line in chunk.replace('<h5>','<h3>').replace('</h5>','</h3>').splitlines())+'\n'
first=episodes[0]; first_ep=episode_config[first['id']]
total_minutes=round(sum(r['podcast']['duration'] for r in episodes)/60)
body=f'''<div class="podcasts-page"><section class="podcast-hero shell" aria-labelledby="page-title"><div class="podcast-hero-copy"><p class="eyebrow"><span class="status-dot" aria-hidden="true"></span>21 CHAPTERS. A NEW WAY TO LISTEN.</p><h1 id="page-title">AI <span>Podcasts</span></h1><p class="podcast-hook">Hear the question.<br>Follow the reasoning.</p><p class="podcast-description">From rising living standards to recessions and inflation, explore the ideas behind the whole economy. Listen at your own pace, jump to a section, or follow the conversation word by word.</p><div class="podcast-hero-actions"><a class="button primary" href="#episodes">Explore the episodes <span aria-hidden="true">↓</span></a><p>Start at Chapter 1, or follow your curiosity.</p></div><div class="collection-facts"><span><strong>21</strong> English episodes</span><span><strong>{total_minutes}</strong> minutes of listening</span><span>Read along as you listen</span></div></div><figure class="podcast-feature" aria-labelledby="featured-title"><div class="feature-top"><span class="eyebrow">YOUR FIRST LISTEN</span><span class="tiny-tag">CHAPTER 01 · {duration_label(first['podcast']['duration'])}</span></div><a class="featured-art" href="#chapter-1" aria-label="Explore Chapter 1: Introduction to Macroeconomics"><img src="{first['preview']}" width="900" height="600" alt="Introduction to Macroeconomics: the chapter mind map" fetchpriority="high"></a><h2 id="featured-title">What can we learn by looking at the whole economy?</h2><p>Income. Jobs. Prices.<br>Start with the questions that connect them.</p><figcaption><button class="feature-listen" type="button" data-podcast-start="{first_ep['id']}-player" hidden><span class="listen-circle" aria-hidden="true">▶</span><span>Start listening<small>Introduction to Macroeconomics · Chapter 1</small></span><span class="listen-arrow" aria-hidden="true">↘</span></button><noscript><a href="#chapter-1">Go to Chapter 1’s audio player ↓</a></noscript></figcaption></figure></section><section class="shell episode-collection" id="episodes" aria-labelledby="episodes-title"><div class="collection-heading"><div><p class="eyebrow">THE LISTENING COLLECTION</p><h2 id="episodes-title">One chapter. One big question.</h2></div><p>Explore the facts. Follow the model.<br>Connect the reasoning to the real world.</p></div>'''
body+='<nav class="episode-directory" aria-label="Jump to a podcast chapter">'+''.join(f'<a href="#chapter-{int(r["id"][2:])}"><span>{r["id"][2:]}</span>{esc(r["title"])}<span class="chapter-arrow" aria-hidden="true">↗</span></a>' for r in episodes)+'</nav>'
body+='<div class="listening-guide"><span class="guide-icon" aria-hidden="true">♫</span><p><strong>Make it your conversation.</strong> Change the speed, revisit a section, or select <strong>Read along</strong> to follow the transcript. Each episode also opens on Spotify.</p><span class="guide-label">LISTEN · PAUSE · REFLECT</span></div>'+searchbox('episodes')+'<div class="episodes">'
for r in episodes:
 e=editorial[r['id']]; ep=episode_config[r['id']]; n=int(r['id'][2:])
